-- Additive application migration. No production data is dropped or reset.
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX products_title_search_idx ON products USING gin(title gin_trgm_ops);
CREATE TABLE guest_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_sha256 char(64) UNIQUE NOT NULL, expires_at timestamptz NOT NULL);
ALTER TABLE carts ADD COLUMN guest_id uuid UNIQUE REFERENCES guest_sessions(id);
ALTER TABLE carts ADD CONSTRAINT carts_actor_check CHECK(num_nonnulls(user_id,guest_id)=1) NOT VALID;
CREATE TABLE guest_wishlists(guest_id uuid REFERENCES guest_sessions(id) ON DELETE CASCADE, product_id uuid REFERENCES products(id) ON DELETE CASCADE, PRIMARY KEY(guest_id,product_id));
ALTER TABLE addresses ADD COLUMN encrypted_payload jsonb;
ALTER TABLE orders ADD COLUMN guest_id uuid REFERENCES guest_sessions(id);
ALTER TABLE orders ADD COLUMN checkout_key text UNIQUE;
ALTER TABLE orders ADD COLUMN request_hash char(64);
ALTER TABLE orders ADD COLUMN payment_method text CHECK(payment_method IN ('COD','RAZORPAY','STORE_CREDIT'));
ALTER TABLE orders ADD COLUMN reservation_expires_at timestamptz;
ALTER TABLE orders ADD COLUMN coupon_id uuid REFERENCES coupons(id);
ALTER TABLE orders ADD COLUMN credit_paise bigint NOT NULL DEFAULT 0 CHECK(credit_paise>=0 AND credit_paise<=total_paise);
ALTER TABLE orders ADD COLUMN payable_paise bigint GENERATED ALWAYS AS(total_paise-credit_paise) STORED;
ALTER TABLE order_items ADD COLUMN discount_paise bigint NOT NULL DEFAULT 0 CHECK(discount_paise>=0 AND discount_paise<=line_total_paise);
ALTER TABLE order_items ADD COLUMN credit_paise bigint NOT NULL DEFAULT 0 CHECK(credit_paise>=0 AND credit_paise<=line_total_paise-discount_paise);
ALTER TABLE inventory_reservations ADD COLUMN state text NOT NULL DEFAULT 'ACTIVE' CHECK(state IN ('ACTIVE','RELEASED','CONSUMED'));
ALTER TABLE payment_attempts ADD COLUMN provider_order_id text;
ALTER TABLE payment_attempts ADD COLUMN request_state text NOT NULL DEFAULT 'NEW';
CREATE UNIQUE INDEX payment_provider_order_unique ON payment_attempts(provider,provider_order_id) WHERE provider_order_id IS NOT NULL;
ALTER TABLE payment_webhook_events ADD COLUMN payload_sha256 char(64);
ALTER TABLE shipments ADD CONSTRAINT shipments_order_unique UNIQUE(order_id);
ALTER TABLE returns ADD COLUMN idempotency_key text UNIQUE;
ALTER TABLE returns ADD COLUMN request_hash char(64);
ALTER TABLE returns ADD COLUMN refund_paise bigint;
ALTER TABLE returns ADD COLUMN credit_paise bigint NOT NULL DEFAULT 0;
ALTER TABLE refunds ADD COLUMN request_state text NOT NULL DEFAULT 'NEW';
ALTER TABLE refunds ADD COLUMN order_id uuid REFERENCES orders(id);
ALTER TABLE variants ADD COLUMN sale_price_paise bigint CHECK(sale_price_paise>=0 AND sale_price_paise<=price_paise);
ALTER TABLE variants ADD COLUMN sale_starts_at timestamptz;
ALTER TABLE variants ADD COLUMN sale_ends_at timestamptz;
ALTER TABLE variants ADD CONSTRAINT sale_window CHECK(sale_ends_at IS NULL OR sale_starts_at IS NULL OR sale_ends_at>sale_starts_at);
ALTER TABLE coupons ADD COLUMN active boolean NOT NULL DEFAULT true;
ALTER TABLE coupons ADD COLUMN minimum_paise bigint NOT NULL DEFAULT 0 CHECK(minimum_paise>=0);
ALTER TABLE coupons ADD CONSTRAINT coupon_percent CHECK(type<>'PERCENT' OR value<=100);
CREATE TABLE credit_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),amount_paise bigint NOT NULL,reason text NOT NULL,event_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX credit_user_idx ON credit_ledger(user_id);
CREATE TABLE loyalty_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),points integer NOT NULL,event_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gift_cards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code_sha256 char(64) UNIQUE NOT NULL,amount_paise bigint NOT NULL CHECK(amount_paise>0),redeemed_by uuid REFERENCES users(id),expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE content_blocks(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),user_id uuid REFERENCES users(id),question text NOT NULL,answer text,approved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_review_per_product_user ON reviews(product_id,user_id);
CREATE TABLE recent_products(user_id uuid REFERENCES users(id) ON DELETE CASCADE,product_id uuid REFERENCES products(id) ON DELETE CASCADE,viewed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,product_id));
ALTER TABLE support_tickets ADD COLUMN guest_id uuid REFERENCES guest_sessions(id);
CREATE TABLE support_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES support_tickets(id),author_id uuid REFERENCES users(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_preferences(user_id uuid PRIMARY KEY REFERENCES users(id),marketing boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),guest_id uuid REFERENCES guest_sessions(id),kind text NOT NULL,title text NOT NULL,event_key text UNIQUE NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mail_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),encrypted_payload jsonb NOT NULL,event_key text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'PENDING',attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE TABLE identity_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('VERIFY_EMAIL','RESET_PASSWORD')),digest char(64) UNIQUE NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE auth_attempts(key char(64) PRIMARY KEY,count integer NOT NULL,reset_at timestamptz NOT NULL);
ALTER TABLE users ADD COLUMN mfa_secret_encrypted jsonb;
ALTER TABLE users ADD COLUMN mfa_last_counter bigint NOT NULL DEFAULT -1;
ALTER TABLE user_sessions ADD COLUMN mfa_verified_at timestamptz;
CREATE TABLE mfa_enrollments(user_id uuid PRIMARY KEY REFERENCES users(id),secret_encrypted jsonb NOT NULL,expires_at timestamptz NOT NULL);
